#include <stdio.h>
#include <stdlib.h>

typedef long long ll;
#define LLINF (1LL<<62)

/* ---------- hash map (open addressing) para chaves de componentes ---------- */
#define HSIZE (1<<19)
#define HMASK (HSIZE-1)
static unsigned long long hkey[HSIZE];
static int hval[HSIZE];
static unsigned char hused[HSIZE];
static int ncomp;
static int *compPrice;

static int compIdFor(unsigned long long key, int price){
    unsigned long long h = key * 0x9E3779B97F4A7C15ULL;
    unsigned idx = (unsigned)(h >> 45);
    while(hused[idx]){
        if(hkey[idx]==key) return hval[idx];
        idx=(idx+1)&HMASK;
    }
    hused[idx]=1; hkey[idx]=key;
    hval[idx]=++ncomp;
    compPrice[ncomp]=price;
    return ncomp;
}

/* ---------- union-find ---------- */
static int parent[100005], stampA[100005], touchedArr[100005];
static int findRoot(int x){
    int r=x;
    while(parent[r]!=r) r=parent[r];
    while(parent[x]!=r){ int nx=parent[x]; parent[x]=r; x=nx; }
    return r;
}

/* ---------- heap binario ---------- */
static ll *hd; static int *hvv; static int hsz;
static void hpush(ll d,int v){
    int c=hsz++;
    hd[c]=d; hvv[c]=v;
    while(c>0){
        int p=(c-1)>>1;
        if(hd[p]<=hd[c]) break;
        ll td=hd[p]; int tv=hvv[p];
        hd[p]=hd[c]; hvv[p]=hvv[c]; hd[c]=td; hvv[c]=tv;
        c=p;
    }
}
static void hpop(ll *d,int *v){
    *d=hd[0]; *v=hvv[0];
    hsz--;
    hd[0]=hd[hsz]; hvv[0]=hvv[hsz];
    int c=0;
    for(;;){
        int l=2*c+1, r=c+1, m=c;
        if(l<hsz && hd[l]<hd[m]) m=l;
        if(r<hsz && hd[r]<hd[m]) m=r;
        if(m==c) break;
        ll td=hd[m]; int tv=hvv[m];
        hd[m]=hd[c]; hvv[m]=hvv[c]; hd[c]=td; hvv[c]=tv;
        c=m;
    }
}

