    for(int v2=0;v2<=NN;v2++) dist[v2]=LLINF;
    hd=(ll*)malloc(((size_t)nec+2)*sizeof(ll));
    hvv=(int*)malloc(((size_t)nec+2)*sizeof(int));
    hsz=0;
    dist[A]=0;
    hpush(0,A);
    ll ans=-1;
    while(hsz>0){
        ll d; int v;
        hpop(&d,&v);
        if(d>dist[v]) continue;
        if(v==B){ ans=d; break; }
        for(int e=hstart[v]; e<hstart[v+1]; e++){
            int to=adjTo[e];
            ll nd=d+(ll)adjW[e];
            if(nd<dist[to]){ dist[to]=nd; hpush(nd,to); }
        }
    }
    printf("%lld\n", ans);
    return 0;
}
